package dev.eugheist.ttmodern;
final class TransvectorPeripheralAudit {
 static void run(net.minecraft.server.level.ServerLevel world,net.minecraft.core.BlockPos at){
  var target=at.east(2);var other=at.west(2);var states=new java.util.LinkedHashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();var tags=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.nbt.CompoundTag>();for(var pos:java.util.List.of(target,other)){states.put(pos,world.getBlockState(pos));var t=world.getBlockEntity(pos);if(t!=null)tags.put(pos,t.saveWithFullMetadata(world.registryAccess()));}
  var context=new dan200.computercraft.api.lua.ILuaContext(){public long issueMainThreadTask(dan200.computercraft.api.lua.LuaTask task){throw new IllegalStateException("Unexpected raw task");}public dan200.computercraft.api.lua.MethodResult executeMainThreadTask(dan200.computercraft.api.lua.LuaTask task)throws dan200.computercraft.api.lua.LuaException {return dan200.computercraft.api.lua.MethodResult.of(task.execute());}};
  try{world.setBlock(at,ThaumicTinkererModern.INTERFACE.get().defaultBlockState(),3);var tile=(TransvectorEntity)world.getBlockEntity(at);var empty=get(world,at);if(!empty.getType().equals(TransvectorPeripheral.UNCONNECTED)||empty.getMethodNames().length!=0)throw new IllegalStateException("CC unconnected transvector shape");
   world.setBlock(target,ThaumicTinkererModern.MAGNET.get().defaultBlockState(),3);world.setBlock(other,ThaumicTinkererModern.MOB_MAGNET.get().defaultBlockState(),3);if(!tile.link(target))throw new IllegalStateException("CC transvector magnet link");var first=get(world,at);if(!first.getType().equals("tt_magnet")||first.getMethodNames().length!=3)throw new IllegalStateException("CC transvector magnet methods");call(first,context,"setPulling",false);if(world.getBlockState(target).getValue(MagnetBlock.PULLING))throw new IllegalStateException("CC transvector forwards annotated method");
   if(!tile.link(other))throw new IllegalStateException("CC transvector mob rebind");var second=get(world,at);if(first.equals(second)||second.getMethodNames().length!=5)throw new IllegalStateException("CC transvector rebind metadata/identity");call(second,context,"setAdultSearch",false);if(((MagnetEntity)world.getBlockEntity(other)).adult)throw new IllegalStateException("CC transvector mob age");call(first,context,"setPulling",false);if(world.getBlockState(other).getValue(MagnetBlock.PULLING))throw new IllegalStateException("CC cached transvector must resolve current link");
   world.setBlock(other,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);var removed=call(second,context,"getAdultSearch").getResult();if(removed!=null&&removed.length!=0||!get(world,at).getType().equals(TransvectorPeripheral.UNCONNECTED))throw new IllegalStateException("CC removed transvector target");
   System.out.println("TT CC TRANSVECTOR PERIPHERAL AUDIT: ALL PASS (unconnected shape,annotated methods,link/rebind metadata,live cached forwarding,removed target)");
  }catch(dan200.computercraft.api.lua.LuaException error){throw new IllegalStateException(error);}finally{states.forEach((pos,state)->world.setBlock(pos,state,3));tags.forEach((pos,data)->{var t=world.getBlockEntity(pos);if(t!=null)t.loadWithComponents(data,world.registryAccess());});}
 }
 private static TransvectorPeripheral get(net.minecraft.server.level.ServerLevel world,net.minecraft.core.BlockPos pos){return (TransvectorPeripheral)world.getCapability(dan200.computercraft.api.peripheral.PeripheralCapability.get(),pos,net.minecraft.core.Direction.UP);}
 private static dan200.computercraft.api.lua.MethodResult call(TransvectorPeripheral p,dan200.computercraft.api.lua.ILuaContext context,String name,Object... args)throws dan200.computercraft.api.lua.LuaException {int index=java.util.Arrays.asList(p.getMethodNames()).indexOf(name);return p.callMethod(null,context,index,new dan200.computercraft.api.lua.ObjectArguments(args));}
}
